package io.github.diodeme.ji.ai;

/** Protocol family implemented by a provider adapter. */
public enum ProviderProtocolFamily {
    OPENAI_COMPATIBLE("openai-compatible"),
    ANTHROPIC("anthropic"),
    GOOGLE("google");

    private final String id;

    ProviderProtocolFamily(String id) {
        this.id = id;
    }

    public String id() {
        return id;
    }
}
